export function m5() {
    return function m6(wrapper) {
        const handler = {
            get: function get(target, name) {
                for (const id in target) {
                    const component = target[id];
                    const exposed = component.m4();
                    if (exposed === null) {
                        const name = component.name;
                        throw new Error(`Cannot invoke component` + ` "${name}}" before $app is ready`);
                    }
                    if (!(name in exposed)) {
                        throw new Error(`Calling undefined member "${name}" ` +
                            `in component "${component.name}"`);
                    }
                    return exposed[name];
                }
            },
        };
        return new Proxy(wrapper, handler);
    };
}
